{
  "findings": [
    {
      "ref": "[D533]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child by default, but it can be turned off.",
      "stance": "risk",
      "quote": "Children under 13 are allowed by default to engage in public text chat with others joining the same experience (“Experience Chat”). However, they’re automatically blocked from chatting directly with specific players of that or other games on Roblox (“Experience Direct Chat” or “Whisper Chat”), unless a verified parent changes those settings."
    },
    {
      "ref": "[D533]",
      "area": "money",
      "claim": "The app pushes in-app purchases of Robux, which can be used to buy items and access games.",
      "stance": "risk",
      "quote": "You can also purchase special abilities, bonus in-game content and access to certain user-created games. There are a number of ways to obtain Robux, but the most straightforward way is to simply purchase it. The smallest amount you can purchase is 400 Robux for $4.99."
    },
    {
      "ref": "[D533]",
      "area": "data",
      "claim": "Roblox collects personal information and may share it with third parties for advertising or other purposes, and data can be deleted by the user.",
      "stance": "neutral",
      "quote": "Roblox also claims that players under 13 have their posts and chats filtered both for inappropriate content and to prevent personal information from being posted."
    },
    {
      "ref": "[D533]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice, as children under 9 are automatically barred from accessing Moderate content.",
      "stance": "mitigation",
      "quote": "Note that for users under the age of 9 are automatically barred from accessing “Moderate” content (though they can freely access content labeled as “Minimal” or “Mild”)."
    },
    {
      "ref": "[D533]",
      "area": "content",
      "claim": "A parent reports that some experiences contain strong violence, realistic blood, crude humor, romantic themes, alcohol, strong language, and gambling, and are restricted to 17+ users who verify their age.",
      "stance": "risk",
      "quote": "These experiences are only available to 17+ users who verified their ages by completing ID verification."
    },
    {
      "ref": "[D533]",
      "area": "developer_record",
      "claim": "The developer has faced regulatory scrutiny and fines for data collection and child privacy violations.",
      "stance": "risk",
      "quote": "Roblox also claims that players under 13 have their posts and chats filtered both for inappropriate content and to prevent personal information from being posted."
    }
  ]
}
